#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# Task 2 driver: migrate every image family to the deterministic FISH overlay (scripts/migrate_overlay.sh), one after
# another, then a short smoke run per Isaac family (scripts/overhead_sweep_v8.sh, IMG_OVERRIDE, lttng x1, SMOKE).
# Usage: scripts/migrate_all.sh <log_dir> [family ...]     (default: all 18 Isaac r2b -wip families)
#   env: SMOKE=1 (default 1) run the smoke after a successful migration; SUFFIX (default fishdeterministic)
set -u
cd "$(dirname "$0")/.."
LD=${1:?log dir}; shift; mkdir -p "$LD"; SUFFIX=${SUFFIX:-fishdeterministic}
FAMS="$*"; [ -z "$FAMS" ] && FAMS="apriltag bi3d bi3d_freespace centerpose detectnet dnn_image_encoder dope ess image_proc nitros_bridge nvblox rtdetr segformer stereo_image_proc tensor_rt triton unet visual_slam"
for F in $FAMS; do
  BASE=fish-r2b-$F-wip:latest; NEW=fish-r2b-$F-$SUFFIX:latest
  docker image inspect $BASE >/dev/null 2>&1 || { echo "$F: base $BASE missing" | tee -a "$LD/migrate_all.txt"; continue; }
  if docker image inspect $NEW >/dev/null 2>&1; then echo "$F: $NEW exists, skipping build" | tee -a "$LD/migrate_all.txt"; else
    T0=$SECONDS; LOG="$LD/migrate_$F.log" bash scripts/migrate_overlay.sh $BASE $NEW ros2_benchmark isaac_ros_benchmark >/dev/null 2>&1
    R=$(grep -c "^COMMITTED" "$LD/migrate_$F.log"); echo "$F: migrate $( [ "$R" = 1 ] && echo OK || echo FAILED ) in $((SECONDS - T0)) s ($(grep -o '[0-9]* symbols to interpose' "$LD/migrate_$F.log" | head -1))" | tee -a "$LD/migrate_all.txt"
    [ "$R" = 1 ] || continue
  fi
  if [ "${SMOKE:-1}" = 1 ]; then
    T0=$SECONDS; IMG_OVERRIDE=$NEW REPS=1 MODES=lttng DEST_BASE="$LD/smoke" SMOKE_TIMEOUT=900 bash scripts/overhead_sweep_v8.sh $F > "$LD/smoke_$F.log" 2>&1
    # a smoke that "finishes" in seconds is a failure: check the run's rc in runs.csv (2026-10-25: ENTRYPOINT bash inherited from the
    # migration container made every run exit 126 and the smoke still reported "done")
    grep -q "^$F,lttng,1,0," "$LD/smoke/runs.csv" 2>/dev/null || echo "$F: SMOKE FAILED (rc != 0 in $LD/smoke/runs.csv)"
    S=$(ls -d "$LD/smoke/$F/lttng_1" 2>/dev/null); echo "$F: smoke $( [ -n "$S" ] && echo done || echo FAILED ) in $((SECONDS - T0)) s" | tee -a "$LD/migrate_all.txt"
  fi
done
echo "ALL DONE $(date +%T)" >> "$LD/migrate_all.txt"
